css:
@page { size: 80mm auto; margin: 0; }
* { box-sizing: border-box; }
body, .print-format { font-family: Arial, Helvetica, sans-serif; color: #000; background: #fff; font-size: 11px; line-height: 1.35; width: 72mm; margin: 0 auto; padding: 2mm 0; }
.receipt-container { width: 100%; }
.receipt-header { text-align: center; padding: 0 0 6px; border-bottom: 1px solid #000; }
.store-logo { display: block; width: 38mm; height: auto; max-height: 18mm; object-fit: contain; margin: 0 auto 1px; }
.store-name { font-size: 12px; font-weight: 700; letter-spacing: 1px; }
.store-registration { font-size: 9px; margin: 2px 0 3px; }
.store-detail { font-size: 10px; line-height: 1.3; }
.store-address { overflow-wrap: break-word; }
.store-contact { margin-top: 2px; }
.invoice-meta { padding: 8px 0; font-size: 10px; }
.meta-row, .total-row, .payment-row, .items-header, .item-detail-line { display: table; width: 100%; table-layout: fixed; }
.meta-row > span, .total-row > span, .payment-row > span, .items-header > span, .item-detail-line > span { display: table-cell; vertical-align: top; overflow-wrap: break-word; word-wrap: break-word; }
.meta-row > span:first-child { width: 26%; }
.meta-row > span:last-child, .total-value, .payment-row > span:last-child { text-align: right; }
.meta-row { margin: 2px 0; }
.meta-label { font-weight: 400; }
.meta-value { font-weight: 600; }
.invoice-number { font-weight: 700; }
hr { border: 0; margin: 0; }
.div-dashed { border-top: 1px dashed #888; margin: 7px 0; }
.receipt-header + .div-dashed { display: none; }
.div-solid { border-top: 1px solid #000; margin: 5px 0; }
.div-double { border-top: 1px solid #000; margin: 7px 0; }
.items-header { font-size: 9px; font-weight: 700; text-transform: uppercase; padding: 4px 0; }
.col-desc { width: 40%; }
.col-qty { width: 12%; text-align: center; }
.col-rate { width: 23%; text-align: right; }
.col-amt { width: 25%; text-align: right; font-weight: 600; }
.item-row { padding: 6px 0; border-bottom: 1px dotted #bbb; page-break-inside: avoid; }
.item-row:last-child { border-bottom: 0; }
.item-name { font-weight: 600; font-size: 11px; margin-bottom: 3px; overflow-wrap: anywhere; }
.item-detail-line { font-size: 10px; }
.item-extras, .item-discount { font-size: 9px; margin-top: 2px; }
.total-row { padding: 2px 0; }
.total-row > span:first-child, .payment-row > span:first-child { width: 65%; }
.total-row.highlight { font-size: 16px; font-weight: 700; padding: 5px 0; }
.totals-section > .div-solid { display: none; }
.payments-section { font-size: 10px; }
.payment-row { padding: 2px 0; }
.return-banner { font-size: 13px; text-align: center; font-weight: 700; padding: 7px 0; border-bottom: 1px solid #000; }
.barcode-section { text-align: center; padding: 7px 0; page-break-inside: avoid; }
.invoice-barcode { font-family: 'Libre Barcode 39', 'Courier New', monospace; font-size: 24px; display: block; line-height: 1; }
.receipt-footer { border-top: 1px solid #000; text-align: center; padding-top: 10px; margin-top: 4px; page-break-inside: avoid; }
.thank-you { font-size: 11px; font-weight: 600; }
.refund-message { font-size: 11px; font-weight: 700; margin-bottom: 5px; }
.powered-by { font-size: 8px; margin-top: 8px; }
@media print { body, .print-format { width: 72mm; margin: 0 auto; padding: 2mm 0; } .page-break { display: none; } }

html:
{% set company_doc = frappe.get_doc("Company", doc.company) %}
{% set pos_profile = frappe.get_doc("POS Profile", doc.pos_profile) if doc.pos_profile else {} %}
{% set company_name = company_doc.company_name or doc.company %}
{% set company_phone = company_doc.phone_no or "" %}
{% set company_email = pos_profile.get("custom_receipt_email") or "" %}
{% set receipt_logo = pos_profile.get("custom_receipt_logo") or company_doc.get("company_logo") %}
{% set registration_no = pos_profile.get("custom_receipt_registration_no") or "" %}
{% set address_name = pos_profile.get("company_address") or company_doc.get("company_address") %}
{% set addr = frappe.get_doc("Address", address_name) if address_name else {} %}
{% set currency = doc.currency or company_doc.default_currency or "MYR" %}
{% set is_return = doc.get("is_return") or (doc.get("grand_total") and doc.grand_total < 0) %}
<div class="receipt-container">
    <div class="receipt-header">
        {% if receipt_logo %}<img class="store-logo" src="{{ receipt_logo | e }}" alt="{{ company_name | e }}">{% endif %}
        <div class="store-name">{{ company_name | e }}</div>
        {% if registration_no %}<div class="store-registration">SSM: {{ registration_no | e }}</div>{% endif %}
        <div class="store-detail">
            <div class="store-address">{% if addr.get("address_line1") %}{{ addr.address_line1 | e }}{% endif %}{% if addr.get("address_line2") %}, {{ addr.address_line2 | e }}{% endif %}{% if addr.get("city") %}, {{ addr.get("pincode", "") | e }} {{ addr.city | e }}{% if addr.get("state") %}, {{ addr.state | e }}{% endif %}{% endif %}</div>
            <div class="store-contact">{% if company_phone %}Tel: {{ company_phone | e }}{% endif %}{% if company_phone and company_email %} | {% endif %}{% if company_email %}{{ company_email | e }}{% endif %}</div>
        </div>
    </div>
    {% if is_return %}
    <div class="return-banner">&#x21A9; RETURN / REFUND</div>
    {% endif %}

    <hr class="div-dashed">

    <div class="invoice-meta">
        <div class="meta-row">
            <span class="meta-label">Invoice:</span>
            <span class="meta-value invoice-number">{{ doc.name }}</span>
        </div>
        <div class="meta-row">
            <span class="meta-label">Date:</span>
            <span class="meta-value">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }} {{ frappe.utils.format_time(doc.posting_time, "hh:mm a") }}</span>
        </div>
        {% if doc.get("owner") and not doc.get("sales_team") %}
        <div class="meta-row">
            <span class="meta-label">Cashier:</span>
            <span class="meta-value">{{ ((frappe.db.get_value("User", doc.owner, "custom_nickname") or "") | trim or "STAFF") | e }}</span>
        </div>
        {% endif %}
        {% if doc.get("sales_team") %}
        <div class="meta-row"><span class="meta-label">Salesperson:</span><span class="meta-value">{% for member in doc.sales_team %}{{ member.sales_person | e }}{% if not loop.last %}, {% endif %}{% endfor %}</span></div>
        {% endif %}
        {% if is_return and doc.get("return_against") %}
        <div class="meta-row return-info" style="text-align:left;">
            <span class="meta-label">Against:</span>
            <span class="meta-value">{{ doc.return_against }}</span>
        </div>
        {% endif %}
    </div>

    <hr class="div-solid">

    <div class="items-header">
        <span class="col-desc">Item</span>
        <span class="col-qty">Qty</span>
        <span class="col-rate">Price</span>
        <span class="col-amt">Total</span>
    </div>

    {% for item in doc.items %}
    <div class="item-row">
        <div class="item-name">{{ (item.get("local_item_name", None) or item.get("item_name")) | e }}</div>
        <div class="item-detail-line">
            <span class="col-desc" style="flex:1;">
                {% if item.item_code != item.item_name %}
                <span style="font-size:9px;color:#333;font-weight:600;">{{ item.item_code | e }}</span>
                {% endif %}
            </span>
            <span class="col-qty">{{ xpos_qty(item.qty) }}</span>
            <span class="col-rate">{{ xpos_number(item.rate) }}</span>
            <span class="col-amt">{{ xpos_number(item.amount) }}</span>
        </div>
        {% if item.uom and item.uom != "Nos" and item.uom != "Unit" %}
        <div class="item-extras">UOM: {{ item.uom }}{% if item.conversion_factor and item.conversion_factor != 1 %}
            (×{{ xpos_qty(item.conversion_factor) }}){% endif %}</div>
        {% endif %}
        {% if item.serial_no %}
        <div class="item-extras">S/N: {{ item.serial_no | e }}</div>
        {% endif %}
        {% if item.batch_no %}
        <div class="item-extras">Batch: {{ item.batch_no | e }}</div>
        {% endif %}
        {% if item.discount_percentage and item.discount_percentage > 0 %}
        {% if pos_profile.get("print_discount_amount") %}
        <div class="item-discount">Discount: {{ frappe.utils.fmt_money(item.discount_amount or ((item.price_list_rate or item.rate) * item.qty * item.discount_percentage / 100), currency=currency) }}</div>
        {% else %}
        <div class="item-discount">Discount: {{ xpos_number(item.discount_percentage) }}%</div>
        {% endif %}
        {% elif item.discount_amount and item.discount_amount > 0 %}
        <div class="item-discount">Discount: {{ frappe.utils.fmt_money(item.discount_amount, currency=currency) }}</div>
        {% endif %}
        {% if item.get("pos_notes") %}
        <div class="item-extras" style="font-style:italic;">&#9998; {{ item.pos_notes | e }}</div>
        {% endif %}
    </div>
    {% endfor %}

    <hr class="div-double">

    <div class="totals-section">
        {% set _rd = {"v": 0} %}
        {% for item in doc.items %}
        {% if item.price_list_rate and item.price_list_rate > item.rate %}
        {% set _ = _rd.update({"v": _rd.v + (item.price_list_rate - item.rate) * (item.qty | abs)}) %}
        {% endif %}
        {% endfor %}
        {% set total_discount_amount = _rd.v + ((doc.discount_amount or 0) | abs) %}
        {% set _subtotal = ((doc.total or 0) | abs) + _rd.v %}
        {% set total_discount_pct = (total_discount_amount / _subtotal * 100) if _subtotal else 0 %}

        {% if total_discount_amount > 0.001 or doc.taxes or doc.get("rounding_adjustment") or doc.get("write_off_amount") %}
        <div class="total-row"><span class="total-label">Subtotal</span><span class="total-value">{{ frappe.utils.fmt_money(_subtotal, currency=currency) }}</span></div>
        {% endif %}

        {% if _rd.v > 0.001 %}
        <div class="total-row discount">
            <span class="total-label">Item Discount</span>
            <span class="total-value">-{{ frappe.utils.fmt_money(_rd.v, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.discount_amount and (doc.discount_amount | abs) > 0 %}
        <div class="total-row discount">
            <span class="total-label">
                Additional Discount
                {% if doc.additional_discount_percentage and not pos_profile.get("print_discount_amount") %} 
                    ({{ doc.additional_discount_percentage }})
                {% endif %}
            </span>
            <span class="total-value">-{{ frappe.utils.fmt_money(doc.discount_amount | abs, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.net_total != doc.total %}
        <div class="total-row">
            <span class="total-label">Net Total</span>
            <span class="total-value">{{ frappe.utils.fmt_money(doc.net_total | abs, currency=currency) }}</span>
        </div>
        {% endif %}

        {% for tax in doc.taxes %}
        <div class="total-row tax">
            <span class="total-label">
                {{ tax.description or "Tax" }}
                {% if tax.rate %} ({{ tax.rate }}%){% endif %}
                {% if tax.included_in_print_rate %} <span style="font-size:7px;">Incl.</span>{% endif %}
            </span>
            <span class="total-value">{{ frappe.utils.fmt_money(tax.tax_amount, currency=currency) }}</span>
        </div>
        {% endfor %}

        {% if doc.get("write_off_amount") and doc.write_off_amount > 0 %}
        <div class="total-row">
            <span class="total-label">Write Off</span>
            <span class="total-value">-{{ frappe.utils.fmt_money(doc.write_off_amount, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.get("rounding_adjustment") and doc.rounding_adjustment != 0 %}
        <div class="total-row" style="font-size:9px;">
            <span class="total-label">Rounding</span>
            <span class="total-value">{{ frappe.utils.fmt_money(doc.rounding_adjustment, currency=currency)
                }}</span>
        </div>
        {% endif %}

        {% if total_discount_amount > 0.001 %}
        <div class="total-row discount">
            <span class="total-label">
                Total Savings
                {% if not pos_profile.get("print_discount_amount") and total_discount_pct > 0 %}
                ({{ "%.1f" | format(total_discount_pct) }}%)
                {% endif %}
            </span>
            <span class="total-value">-{{ frappe.utils.fmt_money(total_discount_amount, currency=currency) }}</span>
        </div>
        {% endif %}

        <hr class="div-solid">

        <div class="total-row highlight">
            <span class="total-label">{{ "REFUND" if is_return else "TOTAL" }}</span>
            <span class="total-value">{{ frappe.utils.fmt_money((doc.rounded_total or doc.grand_total) | abs,
                currency=currency) }}</span>
        </div>
    </div>

    {% if doc.payments and doc.payments | length > 0 %}
    <hr class="div-dashed">
    <div class="payments-section">
        <div class="total-row"
            style="font-size:9px;font-weight:700;text-transform:uppercase;color:#000;margin-bottom:2px;">
            <span>Payment</span>
        </div>
        {% for payment in doc.payments %}
        {% if payment.amount and payment.amount != 0 %}
        {% set tender_currency = payment.get("pos_tender_currency") %}
        {% set is_foreign_tender = tender_currency and tender_currency != currency %}
        <div class="payment-row">
            <span>{{ payment.mode_of_payment | e }}</span>
            <span style="font-weight:700;">
                {% if is_foreign_tender %}
                {{ frappe.utils.fmt_money(payment.get("pos_tender_amount") | abs, currency=tender_currency) }}
                {% else %}
                {{ frappe.utils.fmt_money(payment.amount | abs, currency=currency) }}
                {% endif %}
            </span>
        </div>
        {% if is_foreign_tender %}
        <div class="payment-rate-line" style="font-size:8px;color:#555;padding-left:6px;">
            @ {{ xpos_tender_rate(payment.get("pos_exchange_rate"), currency) }} =
            {{ frappe.utils.fmt_money(payment.amount | abs, currency=currency) }}
        </div>
        {% endif %}
        {% endif %}
        {% endfor %}

        {% set change = doc.get("change_amount") or 0 %}
        {% if change > 0.01 and not is_return %}
        <hr class="div-dashed">
        {% if doc.get("pos_change_legs") %}
        <div class="total-row"
            style="font-size:9px;font-weight:700;text-transform:uppercase;color:#000;margin-bottom:2px;">
            <span>Change</span>
        </div>
        {% for leg in doc.pos_change_legs %}
        <div class="payment-row change-leg-row">
            <span>{{ leg.mode_of_payment | e }}</span>
            <span>{{ frappe.utils.fmt_money(leg.amount, currency=leg.currency or currency) }}</span>
        </div>
        {% endfor %}
        <div class="payment-row change-row" style="font-weight:700;">
            <span>Total Change</span>
            <span>{{ frappe.utils.fmt_money(change, currency=currency) }}</span>
        </div>
        {% else %}
        <div class="payment-row change-row">
            <span>Change</span>
            <span>{{ frappe.utils.fmt_money(change, currency=currency) }}</span>
        </div>
        {% endif %}
        {% endif %}
    </div>
    {% endif %}

    {% if doc.get("loyalty_points") and doc.loyalty_points > 0 %}
    <hr class="div-dashed">
    <div class="total-row" style="font-size:9px;">
        <span class="total-label">&#9733; Loyalty Points Earned</span>
        <span class="total-value" style="color:#8e44ad;">{{ doc.loyalty_points }}</span>
    </div>
    {% endif %}

    {% if doc.get("pos_notes") %}
    <hr class="div-dashed">
    <div style="font-size:9px;color:#000;padding:2px 0;">
        <strong>Notes:</strong> {{ doc.pos_notes | e }}
    </div>
    {% endif %}

    <div class="barcode-section">
        <span class="invoice-barcode">{{ xpos_barcode(doc.name) }}</span>
    </div>

    <div class="receipt-footer">
        {% if is_return %}<div class="refund-message">Refund processed</div>{% endif %}
        <div class="thank-you">{{ (pos_profile.get("custom_receipt_message") or "Thank you for shopping with us.") | e }}</div>
        <div class="powered-by">Powered by {{ (pos_profile.get("custom_receipt_brand") or "LOZiPOS") | e }}</div>
    </div>
</div>
